-- =========================================================================
-- Seed 34 : quizzes for Data Analytics
--
-- One per level, the last one an exam over the whole course. Generated by
-- the shared builder, which refuses to emit a single_choice without exactly
-- one correct option, or a multiple_choice with fewer than two.
-- =========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000038',
   'c0000001-0000-4000-8000-000000000011', 'e0000001-0000-4000-8000-0000000000e4',
   'Level 1 Check: Questions, Distributions and SQL',
   'Turning a question into a metric, reading a distribution, and the join that quietly drops rows.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000039',
   'c0000001-0000-4000-8000-000000000011', 'e0000001-0000-4000-8000-0000000000e8',
   'Level 2 Check: Metrics, Cohorts and Segments',
   'Metric design, reading a retention curve, and the reversal that comes from a changing mix.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000003a',
   'c0000001-0000-4000-8000-000000000011', 'e0000001-0000-4000-8000-0000000000ec',
   'Level 3 Check: Comparison and Inference',
   'What a p-value says, why peeking breaks a test, how uncertainty shrinks, and the alternatives to a causal story.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000003b',
   'c0000001-0000-4000-8000-000000000011', 'e0000001-0000-4000-8000-0000000000f0',
   'Expert Exam: Data Analytics',
   'Dashboards, silent failures, forecasting baselines, and what makes a number defensible.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Questions, Distributions and SQL
  ('a1000001-0000-4000-8000-000000000331', 'f0000001-0000-4000-8000-000000000038', 'multiple_choice',
   'Before computing anything, which of these should a metric definition pin down? Select all that apply.',
   'Population, window and time zone all change the number, and all are routinely left unstated - which is why two analysts produce two answers from one database. What tool computes it changes nothing about the result.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000332', 'f0000001-0000-4000-8000-000000000038', 'single_choice',
   'Spend per customer is 10, 12, 15, 18, 20, 22, 25, 30, 35, 50000. Which summary describes a typical customer?',
   'The median, 21. The mean of 5018 describes nobody: one extreme value has moved it past every other observation. Skewed data is the normal case in business, which is why the median and percentiles are usually the honest summary.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000333', 'f0000001-0000-4000-8000-000000000038', 'single_choice',
   'Why does a filter on the right-hand table in a WHERE clause turn a LEFT JOIN into an INNER JOIN?',
   'Unmatched rows have NULL in every right-hand column, and a WHERE condition on those columns rejects NULL - so exactly the rows the LEFT JOIN preserved are removed again. The condition belongs in the ON clause.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000334', 'f0000001-0000-4000-8000-000000000038', 'single_choice',
   'Which counts distinct customers who ordered?',
   'COUNT(DISTINCT user_id). COUNT(*) counts order rows, so every repeat buyer is counted again; COUNT(user_id) only skips NULLs. Reporting orders as customers overstates your reach and is a very common error.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000335', 'f0000001-0000-4000-8000-000000000038', 'single_choice',
   'Why is WHERE created_at BETWEEN "2026-01-01" AND "2026-01-31" usually wrong?',
   'BETWEEN is inclusive of a timestamp at exactly midnight on the 31st, so everything that happened during that day is excluded. A half-open range - >= the 1st and < the 1st of the next month - is correct and needs no thought about month lengths.',
   2, 5, NULL),

  -- Level 2 Check: Metrics, Cohorts and Segments
  ('a1000001-0000-4000-8000-000000000336', 'f0000001-0000-4000-8000-000000000039', 'single_choice',
   'Why is a rolling 28-day window usually better than a calendar month?',
   'Every 28-day window contains exactly four of each weekday, so weekend effects and month length cannot move the number. Calendar months vary from 28 to 31 days and in weekend count, which produces changes that look like behaviour.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000337', 'f0000001-0000-4000-8000-000000000039', 'single_choice',
   'A retention curve drops steeply and then flattens. What does the flattening mean?',
   'You have found a group the product works for: beyond a point, the remaining users stop leaving. A curve that keeps falling at the same rate means no such group has been found yet, and growth is replacing users rather than accumulating them.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000338', 'f0000001-0000-4000-8000-000000000039', 'single_choice',
   'Your newest cohort shows 0% at month 3. What is the most likely explanation?',
   'Month 3 has not happened yet for that cohort. Showing an incomplete period as 0 rather than blank makes a healthy cohort look like a collapse, and somebody will act on it before anybody checks.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000339', 'f0000001-0000-4000-8000-000000000039', 'single_choice',
   'Treatment A and B convert identically within every segment, yet A is far ahead overall. What has happened?',
   'Simpson paradox: the groups have different mixes of segments, and the segments convert at different rates. A got more of the high-converting segment. The defence is to check the mix before believing any aggregate difference.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-00000000033a', 'f0000001-0000-4000-8000-000000000039', 'multiple_choice',
   'Why should a rate always be reported with its denominator? Select all that apply.',
   'A ratio can move because of either part, and the two call for opposite responses; and a rate from eleven users looks identical on a dashboard to one from eleven thousand. The denominator is what lets a reader discount a small segment automatically.',
   2, 5, NULL),

  -- Level 3 Check: Comparison and Inference
  ('a1000001-0000-4000-8000-00000000033b', 'f0000001-0000-4000-8000-00000000003a', 'single_choice',
   'What does p = 0.03 mean?',
   'It is the probability of seeing a difference at least this large if there were really no difference. It says nothing about the size or importance of the effect, and it is not the probability that the conclusion is correct.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-00000000033c', 'f0000001-0000-4000-8000-00000000003a', 'single_choice',
   'Why does checking an experiment daily and stopping when it becomes significant invalidate it?',
   'Each look is another chance to cross the threshold by luck. Looking repeatedly and stopping at the first crossing means even a true null will eventually appear significant - the false positive rate is far above the one you think you chose.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-00000000033d', 'f0000001-0000-4000-8000-00000000003a', 'single_choice',
   'You have 40 conversions from 1,000 visitors. Roughly what has to happen to halve the uncertainty?',
   'Uncertainty on a proportion shrinks with the square root of the number of events, so four times the data halves the range. This is why small tests cannot detect small effects, no matter how long you stare at them.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-00000000033e', 'f0000001-0000-4000-8000-00000000003a', 'multiple_choice',
   'Accounts using feature X retain better. Which alternatives to "X causes retention" should be ruled out? Select all that apply.',
   'Reverse causation, a confounder and self-selection are the three, and at least one usually applies to an optional feature. Checking whether the retention difference predates adoption is a cheap test of the first.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-00000000033f', 'f0000001-0000-4000-8000-00000000003a', 'single_choice',
   'Which is the strongest evidence that a change caused an effect?',
   'A randomised experiment. Random assignment makes the groups comparable on every variable, including the ones nobody thought to measure - which is exactly what no amount of careful segmentation can promise.',
   2, 5, NULL),

  -- Expert Exam: Data Analytics
  ('a1000001-0000-4000-8000-000000000340', 'f0000001-0000-4000-8000-00000000003b', 'single_choice',
   'A dashboard chart flatlines at zero overnight. What should the design have made obvious?',
   'Whether this is no data or genuinely zero. A failed pipeline and a catastrophic week look identical on most dashboards, which is why freshness, row counts and a gap-rather-than-zero convention matter more than chart choice.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000341', 'f0000001-0000-4000-8000-00000000003b', 'multiple_choice',
   'Which of these change a reported number without raising any error? Select all that apply.',
   'All three. None produce a failure; all produce a different number. They are the reason data needs tests - volume, uniqueness, range, freshness - that run on every refresh rather than being checked when somebody is suspicious.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000342', 'f0000001-0000-4000-8000-00000000003b', 'single_choice',
   'Why compare a forecast against "the same day last week" before trusting a model?',
   'It is the baseline a model has to beat to be worth its complexity, and many do not. Reporting model error without a baseline gives the reader no scale on which to judge whether it is good.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000343', 'f0000001-0000-4000-8000-00000000003b', 'single_choice',
   'Why must forecast error be measured on data the model has not seen?',
   'Error on the fitted data measures memorisation, not prediction. A model complex enough will reproduce history almost exactly and still be useless about next week - which is the same reasoning behind a train/test split in machine learning.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000344', 'f0000001-0000-4000-8000-00000000003b', 'single_choice',
   'You discover a published metric has been wrong for a month. What is the right response?',
   'Say so promptly and plainly: what was wrong, which period, which direction, the corrected figure, and the fix. Quietly correcting it is worse, because somebody acted on the old number and does not know it changed.',
   2, 5, NULL),

  ('a1000001-0000-4000-8000-000000000345', 'f0000001-0000-4000-8000-00000000003b', 'single_choice',
   'A forecast six months out has the same confidence band as next week. What is wrong?',
   'Uncertainty grows with distance, so a band that does not widen is not expressing uncertainty at all. It is a straight line with decoration, and it will be read as a commitment.',
   2, 6, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation), points = VALUES(points);

-- Options are inserted rather than replaced, for the reason seed 14 gives:
-- deleting and re-inserting them would orphan every answer already recorded
-- against them, and a graded attempt whose answers point at nothing is a
-- review that resolves nothing.
INSERT INTO assessment_question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-000000000331' AS question_id, 'Which accounts are included and which are excluded' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000331', 'The time window, and whether it is calendar or rolling', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000331', 'The time zone the day boundary uses', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000331', 'Whether it is computed in SQL or in pandas', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000332', 'The median', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000332', 'The mean', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000332', 'The maximum', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000332', 'The mean, with the outlier included for completeness', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000333', 'Unmatched rows have NULL there, and the WHERE rejects NULL', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000333', 'The optimiser rewrites it for performance', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000333', 'LEFT JOIN only preserves rows when no WHERE clause is present', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000333', 'It does not; the two produce the same rows', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000334', 'COUNT(DISTINCT user_id)', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000334', 'COUNT(*)', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000334', 'COUNT(user_id)', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000334', 'SUM(user_id IS NOT NULL)', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000335', 'It excludes almost all of the 31st, because the bound is midnight', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000335', 'BETWEEN is slower than two comparisons', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000335', 'BETWEEN cannot be used with dates', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000335', 'It includes one extra day at the start', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000336', 'It holds the number of each weekday constant, so month length cannot move it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000336', 'It is easier to compute in SQL', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000336', 'It always produces a larger number, which looks better', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000336', 'Calendar months cannot be compared year on year', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000337', 'There is a core of users the product works for', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000337', 'The data is incomplete for recent periods', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000337', 'Retention is being measured over too short a window', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000337', 'The cohort was too small to be meaningful', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000338', 'Month 3 has not happened yet for them', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000338', 'That cohort churned completely', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000338', 'The cohort was mis-assigned', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000338', 'Retention genuinely falls to zero by month 3', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000339', 'The mix of segments differs between the two groups', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000339', 'The arithmetic is wrong somewhere', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000339', 'The segments are too small to compare', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000339', 'A ran for longer than B', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033a', 'A ratio can move because the denominator changed, not the numerator', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033a', 'A rate from a tiny sample looks the same as one from a large sample', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033a', 'It shows whether the segment is large enough to act on', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033a', 'It is required for the percentage to be computed correctly', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033b', 'A difference this large would be unlikely if there were no real effect', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033b', 'There is a 97% chance the effect is real', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033b', 'The effect is large enough to be worth shipping', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033b', 'The test has enough data to be conclusive', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033c', 'Repeated looks multiply the chance of crossing the threshold by luck', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033c', 'Daily data is noisier than weekly data', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033c', 'The test statistic cannot be computed before the end', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033c', 'It does not; stopping early only costs you precision', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033d', 'Collect about four times as much data', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033d', 'Collect about twice as much data', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033d', 'Run for twice as long, regardless of volume', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033d', 'Nothing; the uncertainty depends on the population size', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033e', 'Engaged users adopt more features, so retention caused the usage', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033e', 'A third factor such as plan size causes both', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033e', 'The users who chose X differ in ways you did not measure', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033e', 'The retention metric was computed on the wrong window', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033f', 'A randomised experiment', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033f', 'A plausible mechanism and the right timing', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033f', 'The effect holding within every segment you checked', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000033f', 'A large sample with a very small p-value', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000340', 'Whether the pipeline failed or the value is really zero', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000340', 'Which team owns the metric', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000340', 'Whether the axis is truncated', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000340', 'The year-on-year comparison', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000341', 'A mobile app starts firing its event on launch rather than on interaction', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000341', 'A filter is added to a shared query to fix one report', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000341', 'Six months of history is backfilled with slightly different logic', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000341', 'A dashboard is moved to a different folder', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000342', 'It is the baseline the model has to beat to justify itself', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000342', 'It removes the trend from the series', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000342', 'It is required to compute a confidence interval', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000342', 'It guarantees the model is not overfitted', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000343', 'Error on fitted data measures memorisation rather than prediction', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000343', 'The fitted data is usually incomplete', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000343', 'It is the only way to compute a confidence interval', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000343', 'Seasonality cannot be measured in sample', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000344', 'Announce it with the period, the direction and the corrected figure', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000344', 'Correct it quietly and monitor whether anyone notices', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000344', 'Wait until the next scheduled review to raise it', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000344', 'Leave the history and apply the fix going forward only', 0, 4
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000345', 'The band should widen with the forecast horizon', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000345', 'Six months is too far to forecast at all', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000345', 'The band should narrow as the trend stabilises', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000345', 'Nothing; a constant band means a stable series', 0, 4
  ) v
